contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool dummy) public payable {
        uint256 callerBalBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert((!reverted && c.balances(address(this)) == 0) || (reverted && address(c).balance >= cBalBefore));
    }

    receive() external payable {}
}

