pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(bool dummy) internal {
        uint256 callerBalBefore;
        try c.balances(address(this)) returns (uint256 __r) { callerBalBefore = __r; } catch { return; }
        uint256 cBalBefore = address(c).balance;
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue((!reverted && c.balances(address(this)) == 0) || (reverted && address(c).balance >= cBalBefore));
    }

    function testFuzz_run(bool dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
